  defaultSeverity?: string;
  /** 评估次数 */
  evaluations?: number;
  /** 触发次数 */
  triggered?: number;
  /** 错误次数 */
  errors?: number;
  /** 触发率（0~1） */
  triggerRate?: number;
  /** 错误率（0~1） */
  errorRate?: number;
  /** 平均耗时（毫秒） */
  avgElapsedMs?: number;
  /** P99 耗时（毫秒） */
  p99ElapsedMs?: number;
  /** 总耗时（毫秒） */
  totalElapsedMs?: number;
